  // Shallow copy the user provided router options to prevent mutating them:
  // the same options object may be reused to build several instances, and some
  // of the values filled in below (such as `defaultRoute` and `onBadUrl`) are
  // bound to a single instance.
  const routerOptions = Object.assign(Object.create(null), options.routerOptions)

